start.dailystats/buckets.py:
"""Day buckets for the daily statistics: every reading belongs to the UTC calendar day of its timestamp."""
from datetime import datetime


def day_key(ts):
    """"YYYY-MM-DD" of the UTC day that contains the Unix timestamp `ts`."""
    return datetime.fromtimestamp(ts).strftime("%Y-%m-%d")

