"""Totals for the licence list: one `name,amount,status` line per entry."""


def active_total(path):
    """Sum of the amounts of all entries whose status is exactly "active"."""
    total = 0
    with open(path, newline="") as fh:
        for line in fh.read().split("\n"):
            if not line:
                continue
            name, amount, status = line.split(",")
            if status == "active":
                total += int(amount)
    return total

